import{z as B,x as c,o as E,c as n,q as l,j as t,D as e,d as o,s as i,S as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"缓存命中经济学","description":"","frontmatter":{"title":"缓存命中经济学","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ce-cache-economics.md","filePath":"llm/ce-cache-economics.md","lastUpdated":1791413859000}'),p={name:"llm/ce-cache-economics.md"};function s(h,a,_,d,D,m){const r=c("Mermaid");return E(),n("div",null,[a[2]||(a[2]=l('<h1 id="缓存命中经济学" tabindex="-1">缓存命中经济学 <a class="header-anchor" href="#缓存命中经济学" aria-label="Permalink to &quot;缓存命中经济学&quot;">​</a></h1><div class="epigraph"><p>缓存把一次昂贵的计算换成一次便宜的读取；省多少不取决于缓存本身，取决于你的前缀里有多少是重复的。</p><footer>—— 据开放 API 提示缓存计费口径与本仓库前缀缓存课、KV 成本模型课整理</footer></div><p><a href="/llm/ce-batch-economics">上一课</a>把批写成单价函数，工作点钉在 SLO 允许的最大批，并指出输入重流量里批的杠杆让位——让给本课。进入课程的优化杠杆单元，第一个杠杆直接改请求形状：前缀缓存把重复的 prefill 变成一次读取。本课写它的期望成本账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「有缓存所以省」是一句没有数字的话。缓存的收益由命中率决定，命中率由前缀结构决定：系统提示是否所有请求共享、知识段是否按库稳定、用户动态内容是否被错误地放在了前面。结构错了，缓存条目存了一堆永不复用的 KV，占着显存还把批容量挤小——缓存从杠杆变成税。缺口是把缓存写成期望成本函数，让「前缀怎么排」从工程直觉变成可以算的题。</p><h3 id="命中账" tabindex="-1">命中账 <a class="header-anchor" href="#命中账" aria-label="Permalink to &quot;命中账&quot;">​</a></h3><p>未命中每 token 付 prefill 单价 \\(c_p\\)，命中付读取价 \\(c_r\\)（公开计费口径约为 prefill 的四分之一或更低，物理上对应「不再算、只搬运」）。设命中 token 比例为 \\(h\\)，则每 token 期望成本</p> \\[\\bar{c} = (1-h)\\,c_p + h\\,c_r = c_p - h\\,(c_p - c_r) \\]<p>收益 \\(h\\,(c_p - c_r)\\) 对 \\(h\\) 线性，斜率是价差：命中率从零到六成的收益，是价差乘以零点六。这条线性关系是设计的前半；后半是 \\(h\\) 从哪来。<a href="/llm/kv-prefix-cache">前缀缓存课</a>讲过共享的结构（跨请求的公共前缀、会话续接、树形组织），<a href="/llm/lc-context-cache-tiers">上下文缓存分层课</a>把库级、会话级、请求级的层与账分开；本课只取结论：\\(h\\) 由「公共前缀占请求的比例」上界封顶，工程的全部工作是逼近这个上界。</p><p><span class="marginnote">数字实例：设 \\(c_p = 3\\) 美元/百万 token、\\(c_r = 0.75\\) 美元/百万 token（约为四分之一），价差 2.25。命中率 \\(h = 0.6\\) 时，每百万输入 token 省下 \\(0.6 \\times 2.25 = 1.35\\) 美元，期望成本从 3 美元降到 1.65 美元——省多少完全由 \\(h\\) 和价差这两个数决定。</span></p>',10)),(E(),t(A,null,{default:e(()=>[i(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20PRE%7B%22%E5%89%8D%E7%BC%80%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20PRE%20--%3E%7C%E5%91%BD%E4%B8%AD%20h%7C%20READ%5B%22%E8%AF%BB%20KV%EF%BC%9A%E4%BB%98%20c_r%22%5D%0A%20%20PRE%20--%3E%7C%E6%9C%AA%E5%91%BD%E4%B8%AD%201-h%7C%20PF%5B%22prefill%EF%BC%9A%E4%BB%98%20c_p%22%5D%0A%20%20READ%20--%3E%20OUT%5B%22%E6%8B%BC%E6%8E%A5%E5%90%8E%E8%BF%9B%E5%85%A5%20decode%22%5D%0A%20%20PF%20--%3E%20OUT%0A%20%20OUT%20--%3E%20ACCT%5B%22%E6%9C%9F%E6%9C%9B%E6%88%90%E6%9C%AC%20c%CC%84%20%3D%20(1-h)c_p%20%2B%20h%C2%B7c_r%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把前缀当缓存键来设计：稳定段（系统提示、工具定义、领域知识库的固定段）放最前，易变段（检索结果、用户输入、时间戳）放最后；会话多轮把历史整体续接而不是每轮重排。三步落地：先量——按前缀指纹统计现有流量的可共享比例，得到 \\(h\\) 的理论上界；再排——把请求模板按「公共段长度」重写，逼近上界；后守——容量与驱逐策略保住已命中的条目，驱逐率的账单独立记，因为驱逐打掉的是已经付过设计成本的收益。</p><p><span class="marginnote">直觉类比：把前缀想成图书馆排架——人人都查的那本大字典放在最外面，谁来都翻同一份；若把每个读者各异的借书单插进字典中间，后面的人翻到的页码就全对不上。「公共段在前、易变段在后」做的正是让这份共享字典尽可能长。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓存的三笔隐藏账决定了它不是纯赚。容量账：缓存条目占 KV 显存，挤占批空间——上一课的单价函数里 \\(T_{\\max}\\) 会因此下移，容量紧张时缓存要与批抢显存，这是真实的权衡而非实现瑕疵。驱逐账：容量不足触发驱逐，命中率先跌的是长尾会话，重算一次付全价 prefill。一致性账：模板一改，旧前缀全部失效，改模板要按「缓存代际」排期——这也是设计成本。为什么「系统提示放最前」永远是对的：命中结构由前缀的公共子串决定，公共段越靠前、越长，跨请求共享越彻底；把时间戳插在系统提示中间，等于亲手把公共串切断。</p>',5)),(E(),t(A,null,{default:e(()=>[i(r,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20KV%5B%22KV%20%E7%BC%93%E5%AD%98%E6%9D%A1%E7%9B%AE%22%5D%20--%3E%20MEM%5B%22%E5%8D%A0%E6%8D%AE%20KV%20%E6%98%BE%E5%AD%98%22%5D%0A%20%20MEM%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E8%B4%A6%EF%BC%9A%E6%89%B9%E5%AE%B9%E9%87%8F%E8%A2%AB%E6%8C%A4%E5%8D%A0%22%5D%0A%20%20MEM%20--%3E%20EV%5B%22%E9%A9%B1%E9%80%90%E8%B4%A6%EF%BC%9A%E5%AE%B9%E9%87%8F%E4%B8%8D%E8%B6%B3%E8%A7%A6%E5%8F%91%E9%A9%B1%E9%80%90%22%5D%0A%20%20EV%20--%3E%20DROP%5B%22%E9%95%BF%E5%B0%BE%E4%BC%9A%E8%AF%9D%E5%91%BD%E4%B8%AD%E7%8E%87%E5%85%88%E8%B7%8C%22%5D%0A%20%20DROP%20--%3E%20REPAY%5B%22%E9%87%8D%E7%AE%97%E4%B8%80%E6%AC%A1%EF%BC%9A%E8%A1%A5%E4%BB%98%E5%85%A8%E4%BB%B7%20c_p%22%5D%0A%20%20TPL%5B%22%E4%BF%AE%E6%94%B9%E8%AF%B7%E6%B1%82%E6%A8%A1%E6%9D%BF%22%5D%20--%3E%20INV%5B%22%E4%B8%80%E8%87%B4%E6%80%A7%E8%B4%A6%EF%BC%9A%E6%97%A7%E5%89%8D%E7%BC%80%E6%95%B4%E4%BD%93%E5%A4%B1%E6%95%88%22%5D%0A%20%20INV%20--%3E%20REPAY%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p><span class="marginnote">常见误区：初学者容易以为缓存条目越多越赚。实际上每条缓存都是一块占着显存的 KV——存一堆永不复用的条目，等于用批容量替它们交房租；而驱逐掉一个正被共享的长前缀，下次命中失败还要补付全价 prefill。</span></p><p><span class="marginnote">计费口径的提醒：公开 API 的缓存折扣价是定价策略，物理省下的是 prefill 算力与时延；自建集群的收益表用 \\(h\\,(c_p - c_r)\\) 按自己的实测单价算，不要拿零售折扣当物理常数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>缓存只省 prefill，一个字节的 decode 都不省——输出重的流量里缓存杠杆同样让位，让给模型谱系上的操作（下两课）。命中率是流量结构的函数：单租户模板统一的流量命中高，多租户杂讯大的流量命中天然低，跨业务比较命中率没有意义。最后，缓存改变的是请求形状而不是模型能力，质量的门禁照走：模板重排是行为变更，必须重跑评测再放量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>期望成本 \\(\\bar{c}=(1-h)c_p+h\\,c_r\\)：收益对命中率线性，斜率是 prefill 与读取的价差。</li><li>命中率由前缀的公共子串上界封顶；稳定段前置、易变段后置、会话整体续接是逼近上界的标准动作。</li><li>缓存有容量、驱逐、一致性三笔隐藏账，模板变更要按缓存代际排期。</li><li>缓存只作用于 prefill；输出重流量与 decode 的账在别的杠杆里。</li><li>出处：计费折扣按开放 API 公开口径整理；共享结构与分层记账见本仓库前缀缓存课、上下文缓存分层课、KV 成本模型课。</li></ul>',6))])}const P=B(p,[["render",s]]);export{f as __pageData,P as default};
